import { revalidatePath } from "next/cache";
import { toggleNotifications } from "./lib/user";

export async function toggleNotificationsAction(formData: FormData) {
  const userId = formData.get("userId") as string;

  toggleNotifications(userId);

  revalidatePath("/");
}

