import { toggleNotificationsAction } from "./actions";
import { getUserPreferences } from "./lib/user";

const USER_ID = "current-user";

export default async function Home() {
  const { notificationsEnabled } = getUserPreferences(USER_ID);

  return (
    <main>
      <h1>Settings</h1>

      <form action={toggleNotificationsAction}>
        <input type="hidden" name="userId" value={USER_ID} />
        <button type="submit">
          Notifications: {notificationsEnabled ? "On" : "Off"}
        </button>
      </form>
    </main>
  );
}

